package db_test

// The armory importer (AOC-011), against a real database.
//
// ⚠️ EVERY FIXTURE NAME IS OBVIOUSLY FAKE — "Test Blade Alpha", "Test Boss Gamma". The taxonomy
// VALUES are real because they must resolve against AOC-009's seeds, but nothing here invents a
// game fact (CLAUDE.md STEP ZERO).
//
// What these pin, in order of how much they would have hurt:
//  1. an unresolvable value aborts the transaction and leaves ZERO rows — the import never
//     half-writes and never guesses;
//  2. re-running changes nothing — the snapshot is regenerated by every data-quality ticket, so
//     this import WILL be run again;
//  3. the counts the importer reports are the counts in the database;
//  4. the two exclusions Pierre decided on actually exclude.

import (
	"context"
	"database/sql"
	"strings"
	"testing"

	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/pierrehrt/aoc-api/internal/items"
)

