type importResult struct {
	rep *items.Report
	err error
}

func runImport(t *testing.T, pool *pgxpool.Pool, body string) importResult {
	t.Helper()
	ctx := context.Background()
	its, err := items.DecodeSnapshot(strings.NewReader(body))
	if err != nil {
		t.Fatalf("decoding fixture: %v", err)
	}
	tx, err := pool.Begin(ctx)
	if err != nil {
		t.Fatalf("begin: %v", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()

	l, err := items.LoadLookups(ctx, tx)
	if err != nil {
		t.Fatalf("lookups: %v", err)
	}
	rep, err := items.Import(ctx, tx, its, l)
	if err == nil {
		if cerr := tx.Commit(ctx); cerr != nil {
			t.Fatalf("commit: %v", cerr)
		}
	}
	return importResult{rep: rep, err: err}
}

func TestTheFixtureImportsWithTheCountsItReports(t *testing.T) {
	pool, d := importTarget(t)
	r := runImport(t, pool, fixtureJSON)
	if r.err != nil {
		t.Fatalf("import: %v", r.err)
	}

	// 3 items in, 1 excluded by Pierre's decision -> 2 land.
	for table, want := range map[string]int{
		"items":                2,
		"item_stats":           2, // both on the blade; the ring and relic have none
		"item_spell_effects":   1, // kept apart from stats, deliberately
		"item_sources":         2, // 3 on the blade, 1 of them quarantined
		"item_costs":           2, // one source, two currencies
		"item_classes":         1,
		"item_equip_locations": 4, // blade both slots + ring either slot; relic none
		"sets":                 1,
		"vendors":              1,
	} {
		if got := count(t, d, table); got != want {
			t.Errorf("%s has %d rows, want %d", table, got, want)
		}
		if r.rep.Counts[table] != want {
			t.Errorf("the report claims %s=%d, want %d", table, r.rep.Counts[table], want)
		}
	}

	if len(r.rep.ExcludedItems) != 1 || !strings.Contains(r.rep.ExcludedItems[0], "9003") {
		t.Errorf("excluded items = %v, want the one flagged item", r.rep.ExcludedItems)
	}
	if r.rep.HeldSources != 1 {
		t.Errorf("held sources = %d, want 1", r.rep.HeldSources)
	}
	if len(r.rep.ItemsNoSources) != 1 || r.rep.ItemsNoSources[0] != 9002 {
		t.Errorf("items with no source = %v, want [9002]", r.rep.ItemsNoSources)
	}
}

// The snapshot is regenerated by every data-quality ticket, so this import will be run again.
func TestReRunningTheImportChangesNothing(t *testing.T) {
	pool, d := importTarget(t)
	if r := runImport(t, pool, fixtureJSON); r.err != nil {
		t.Fatalf("first import: %v", r.err)
	}
	first := snapshotCounts(t, pool, d)
	if r := runImport(t, pool, fixtureJSON); r.err != nil {
		t.Fatalf("second import: %v", r.err)
	}
	second := snapshotCounts(t, pool, d)
	for k, v := range first {
		if second[k] != v {
			t.Errorf("%s: %d rows after the first import, %d after the second", k, v, second[k])
		}
	}
}

// The whole point of the pre-flight: a value nobody has decided about stops everything, and
// stops it BEFORE anything is written.
func TestAnUnresolvableValueWritesNothingAtAll(t *testing.T) {
	pool, d := importTarget(t)
	bad := strings.Replace(fixtureJSON, `"rarity":"Epic"`, `"rarity":"Ultra Legendary Plus"`, 1)

	ctx := context.Background()
	its, err := items.DecodeSnapshot(strings.NewReader(bad))
	if err != nil {
		t.Fatalf("decoding: %v", err)
	}
	tx, err := pool.Begin(ctx)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	l, err := items.LoadLookups(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	unknown, _ := items.CheckResolvable(its, l)
	// Staleness is not asserted here: this fixture deliberately contains none of the four
	// recorded values, so all four are stale by construction. TestTheDecidedListIsAuditedAgainstTheData
	// is where that behaviour is pinned.
	if len(unknown) != 1 || unknown[0].Value != "Ultra Legendary Plus" {
		t.Fatalf("pre-flight found %v, want only the one unknown rarity", unknown)
	}
	// And nothing was written on the way to finding out.
	if got := count(t, d, "items"); got != 0 {
		t.Errorf("items has %d rows after a refused import, want 0", got)
	}
}

// A decision that no longer matches anything must fail too, or the list rots into an exemption
// nobody rechecks — the AOC-019/AOC-020/AOC-032 shape.
func TestTheDecidedListIsAuditedAgainstTheData(t *testing.T) {
	pool, _ := importTarget(t)
	ctx := context.Background()
	its, _ := items.DecodeSnapshot(strings.NewReader(fixtureJSON))
	tx, err := pool.Begin(ctx)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	l, _ := items.LoadLookups(ctx, tx)

	_, stale := items.CheckResolvable(its, l)
	// The fixture contains none of the four recorded values, so every one of them is stale here.
	if len(stale) != 4 {
		t.Errorf("got %d stale decisions on a fixture that triggers none of them, want 4: %v",
			len(stale), stale)
	}
	for _, s := range stale {
		if !strings.Contains(s, "decided list") {
			t.Errorf("a stale-decision message does not explain itself: %q", s)
		}
	}
}

// importTarget gives a migrated throwaway database as both a pool (what the importer needs) and
// a *sql.DB (what this package's count() helper needs). Same database, two handles.
func importTarget(t *testing.T) (*pgxpool.Pool, *sql.DB) {
	t.Helper()
	d, url := migratedDB(t)
	pool, err := pgxpool.New(context.Background(), url)
	if err != nil {
		t.Fatalf("pool: %v", err)
	}
	t.Cleanup(pool.Close)
	return pool, d
}

func snapshotCounts(t *testing.T, pool *pgxpool.Pool, d *sql.DB) map[string]int {
	t.Helper()
	_ = pool
	out := map[string]int{}
	for _, table := range []string{"items", "item_stats", "item_spell_effects", "item_sources",
		"item_costs", "item_classes", "item_equip_locations", "sets", "vendors"} {
		out[table] = count(t, d, table)
	}
	return out
}
